import type { Cart } from "../cart/types";
import { discountOff } from "../cart/discount";

/** What the shopper is charged: the cart's items and shipping, less its discount code. */
export function chargeTotal(cart: Cart, shipping: number): number {
  const items = cart.items.reduce((sum, i) => sum + i.price * i.qty, 0);
  return round(items + shipping - discountOff(cart, items + shipping));
}

const round = (n: number) => Math.round(n * 100) / 100;

