/** The shopper picked a shipping speed: the total shown and charged is recomputed. */
export function onShippingChange(cart: Cart, speed: "standard" | "express"): { shipping: number; total: number } {
  const shipping = speed === "express" ? 12 : 0;
  // The cart page applied the discount to its own display; the total here starts from the items again.
  return { shipping, total: chargeTotal(cart, shipping) };
