import { chargeTotal } from "./total";
import type { Cart } from "../cart/types";

/** The shopper picked a shipping speed: the total shown and charged is recomputed, discount included. */
export function onShippingChange(cart: Cart, speed: "standard" | "express"): { shipping: number; total: number } {
  const shipping = speed === "express" ? 12 : 0;
  return { shipping, total: chargeTotal(cart, shipping) };
}

import { expect, test } from "bun:test";
import { onShippingChange } from "../../src/checkout/shipping";

test("discount survives a shipping change", () => {
  const cart = { items: [{ sku: "mug", price: 24, qty: 3 }], code: { id: "SAVE15", percent: 15 } };
  // 72.00 of items and 12.00 express shipping, 15% off the order: what the cart showed.
  expect(onShippingChange(cart, "express").total).toBe(71.4);
});
